CREATE EXTENSION IF NOT EXISTS pg_cron;
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'refresh-landing-pages';
SELECT cron.schedule('refresh-landing-pages', '30 4 * * *', $cron$ SET statement_timeout = '20min'; SELECT public.refresh_landing_pages(); $cron$);
CREATE OR REPLACE FUNCTION public.promo_item_label(p_product text, p_city uuid, p_dish uuid, p_page_slug text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT CASE WHEN p_product IN ('uitgelicht', 'topplek') THEN (CASE p_product WHEN 'topplek' THEN 'Topplek' ELSE 'Uitgelicht' END) || ' op de pagina ' || coalesce((SELECT s.subject || ' in ' || s.city_name FROM public.page_subject(p_page_slug) s), p_page_slug) ELSE 'Vraag doorsturen voor ' || coalesce((SELECT name FROM public.dishes WHERE id = p_dish), 'je gerecht') || ' in ' || coalesce((SELECT name FROM public.cities WHERE id = p_city), 'je stad') END $$;
CREATE OR REPLACE FUNCTION public.promo_auction_reminders() RETURNS TABLE (user_id uuid, email text, restaurant_name text, product text, label text, role text, my_cents int, highest_bid_cents int, open_bids int, auction_date date) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH d AS (SELECT public.promo_quarter_end(current_date) + 1 AS auction_date), routing_bids AS (SELECT b.market_id, count(*)::int n, max(b.amount_cents) hi FROM public.promo_bids b JOIN public.promo_markets m ON m.id = b.market_id AND m.product = 'routing' WHERE b.status = 'open' GROUP BY b.market_id), page_bids AS (SELECT m.product, b.page_slug, count(*)::int n, max(b.amount_cents) hi FROM public.promo_bids b JOIN public.promo_markets m ON m.id = b.market_id WHERE b.status = 'open' AND b.page_slug IS NOT NULL GROUP BY m.product, b.page_slug), rows AS (SELECT s.user_id, s.restaurant_id, 'routing'::text product, public.promo_item_label('routing', m.city_id, m.dish_id, NULL) label, 'holder'::text role, s.price_cents my_cents, rb.hi, rb.n FROM public.promo_slots s JOIN public.promo_markets m ON m.id = s.market_id JOIN routing_bids rb ON rb.market_id = s.market_id WHERE s.status = 'active' AND EXISTS (SELECT 1 FROM public.promo_bids b WHERE b.market_id = s.market_id AND b.status = 'open' AND b.restaurant_id <> s.restaurant_id) UNION ALL SELECT o.user_id, o.restaurant_id, k.kind, public.promo_item_label(k.kind, NULL, NULL, o.page_slug), 'holder', o.amount_cents, pb.hi, pb.n FROM public.package_orders o CROSS JOIN LATERAL (SELECT CASE WHEN o.package IN ('topplek', 'dominant') THEN 'topplek' ELSE 'uitgelicht' END AS kind) k JOIN page_bids pb ON pb.page_slug = o.page_slug AND pb.product = k.kind WHERE o.package IN ('founding_partner', 'groei', 'topplek', 'dominant') AND public.founding_partner_live(o.status) AND o.plan = 'month' AND NOT public.pp_protected(k.kind, o.created_at, o.plan, o.current_period_end) AND EXISTS (SELECT 1 FROM public.pp_bids(k.kind, o.page_slug) b WHERE b.status = 'open' AND b.restaurant_id <> o.restaurant_id) UNION ALL SELECT b.user_id, b.restaurant_id, m.product, public.promo_item_label(m.product, m.city_id, m.dish_id, b.page_slug), 'bidder', b.amount_cents, coalesce(rb.hi, pb.hi), coalesce(rb.n, pb.n) FROM public.promo_bids b JOIN public.promo_markets m ON m.id = b.market_id LEFT JOIN routing_bids rb ON rb.market_id = b.market_id AND b.page_slug IS NULL LEFT JOIN page_bids pb ON pb.page_slug = b.page_slug AND pb.product = m.product WHERE b.status = 'open') SELECT r.user_id, p.email, rs.name, r.product, r.label, r.role, r.my_cents, r.hi, r.n, d.auction_date FROM rows r CROSS JOIN d JOIN public.profiles p ON p.id = r.user_id JOIN public.restaurants rs ON rs.id = r.restaurant_id WHERE p.email IS NOT NULL $$;
CREATE OR REPLACE FUNCTION public.promo_action_mail(p_product text, p_slot uuid, p_bid uuid) RETURNS TABLE (email text, restaurant_name text, label text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.email, rs.name, x.label FROM (SELECT s.user_id, s.restaurant_id, public.promo_item_label('routing', m.city_id, m.dish_id, NULL) label FROM public.promo_slots s JOIN public.promo_markets m ON m.id = s.market_id WHERE p_product = 'routing' AND s.id = p_slot UNION ALL SELECT o.user_id, o.restaurant_id, public.promo_item_label(p_product, NULL, NULL, o.page_slug) FROM public.package_orders o WHERE p_product IN ('uitgelicht', 'topplek') AND o.id = p_slot UNION ALL SELECT b.user_id, b.restaurant_id, public.promo_item_label(m.product, m.city_id, m.dish_id, b.page_slug) FROM public.promo_bids b JOIN public.promo_markets m ON m.id = b.market_id WHERE b.id = p_bid) x JOIN public.profiles p ON p.id = x.user_id JOIN public.restaurants rs ON rs.id = x.restaurant_id LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.promo_item_label(text, uuid, uuid, text) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION public.promo_auction_reminders() FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION public.promo_action_mail(text, uuid, uuid) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.promo_item_label(text, uuid, uuid, text), public.promo_auction_reminders(), public.promo_action_mail(text, uuid, uuid) TO service_role;